 html+='<div class="cal">'+days.map((w,i)=>{const d=isCur&&chal.cur.done[i];return'<button class="'+(d?"done ":"")+(i===nx?"next ":"")+(w===REST?"rest":"")+'" onclick="L.chDay(\''+id+'\','+i+')">'+(w===REST&&!d?"😴":(i+1))+'</button>'}).join("")+'</div>';
