const MEALS={b:"Breakfast",l:"Lunch",d:"Dinner",s:"Snacks"};
let mealTab="b";
function todaysMeal(){const h=new Date().getHours(),m=h<11?"b":h<15?"l":h<20?"d":"s",list=RECIPES.filter(r=>r.m===m),n=Math.floor(Date.now()/864e5);return list[n%list.length]}
function openMeals(tab){if(tab)mealTab=tab;const t=targets(),eaten=(D().m||[]).map(id=>RECIPES.find(r=>r.id===id)).filter(Boolean),kc=eaten.reduce((a,r)=>a+r.kcal,0),pr=eaten.reduce((a,r)=>a+r.p,0);
 document.getElementById("lifeSheet").innerHTML='<div class="sheet-top"><span class="eyebrow">MEAL IDEAS</span><button class="close" onclick="closeModal(\'lifeModal\')">×</button></div><div class="facts3"><div><b>'+kc.toLocaleString("en-GB")+'</b><small>KCAL TODAY</small></div><div><b>'+(t.kcal?t.kcal.toLocaleString("en-GB"):"")+'</b><small>ROUGH TARGET</small></div><div><b>'+pr+' g</b><small>PROTEIN</small></div></div><div class="seg">'+Object.entries(MEALS).map(([k,v])=>'<button class="'+(mealTab===k?"active":"")+'" onclick="L.openMeals(\''+k+'\')">'+v+'</button>').join("")+'</div><div style="margin-top:8px">'+RECIPES.filter(r=>r.m===mealTab).map(r=>'<div class="recipe" onclick="L.recipe(\''+r.id+'\')"><span class="em">'+r.em+'</span><div><b>'+esc(r.n)+'</b><small>'+r.kcal+' kcal · '+r.p+' g protein · '+r.min+' min'+(r.v?" · veggie":"")+'</small></div>'+((D().m||[]).includes(r.id)?'<span class="eaten">✓ HAD IT</span>':'')+'</div>').join("")+'</div><p class="tiny" style="text-align:center;margin-top:10px">Rough figures per portion. General guidance, not medical or dietary advice.</p>';openModal("lifeModal")}
function recipe(id){const r=RECIPES.find(x=>x.id===id),had=(D().m||[]).includes(id);document.getElementById("lifeSheet").innerHTML='<div class="sheet-top"><button class="linkbtn" onclick="L.openMeals()">‹ Meals</button><button class="close" onclick="closeModal(\'lifeModal\')">×</button></div><div style="font-size:64px;text-align:center">'+r.em+'</div><h2 style="text-align:center;margin:4px 0">'+esc(r.n)+'</h2><div class="facts3"><div><b>'+r.kcal+'</b><small>KCAL</small></div><div><b>'+r.p+' g</b><small>PROTEIN</small></div><div><b>'+r.min+'</b><small>MINUTES</small></div></div><h3>You need</h3><ul class="ol">'+r.ing.map(i=>'<li>'+esc(i)+'</li>').join("")+'</ul><h3>Method</h3><ol class="ol">'+r.how.map(i=>'<li>'+esc(i)+'</li>').join("")+'</ol><button class="btn full" style="margin-top:14px;padding:16px;'+(had?"":"background:var(--grad);color:#fff")+'" onclick="L.ate(\''+id+'\')">'+(had?"✓ Had it today (tap to undo)":"I had this today")+'</button>';openModal("lifeModal")}
function ate(id){const d=D(),a=d.m||(d.m=[]),i=a.indexOf(id);if(i>=0)a.splice(i,1);else{a.push(id);toast("Added to today")}saveDaily();recipe(id);renderLifeToday()}

/* ---------- breathing ---------- */
const BREATHS={calm:{n:"Calm",sub:"In 4, hold 7, out 8",ph:[["In",4],["Hold",7],["Out",8]]},box:{n:"Focus",sub:"In 4, hold 4, out 4, hold 4",ph:[["In",4],["Hold",4],["Out",4],["Hold",4]]},reset:{n:"Quick reset",sub:"In 4, out 6",ph:[["In",4],["Out",6]]}};
let B=null;
function openBreath(){document.getElementById("lifeSheet").innerHTML='<div class="sheet-top"><span class="eyebrow">BREATHE</span><button class="close" onclick="closeModal(\'lifeModal\')">×</button></div>'+Object.entries(BREATHS).map(([k,b])=>'<div class="recipe" onclick="L.breathLen(\''+k+'\')"><span class="em">'+({calm:"🌙",box:"🔲",reset:"🌬️"})[k]+'</span><div><b>'+b.n+'</b><small>'+b.sub+'</small></div></div>').join("");openModal("lifeModal")}
function breathLen(k){document.getElementById("lifeSheet").innerHTML='<div class="sheet-top"><button class="linkbtn" onclick="L.openBreath()">‹ Back</button><button class="close" onclick="closeModal(\'lifeModal\')">×</button></div><h2 style="text-align:center">'+BREATHS[k].n+'</h2><div class="bigtap"><button onclick="L.breathGo(\''+k+'\',60)">1 min</button><button onclick="L.breathGo(\''+k+'\',180)">3 min</button><button onclick="L.breathGo(\''+k+'\',300)">5 min</button></div>';openModal("lifeModal")}
function breathGo(k,secs){closeModal("lifeModal");unlockAudio();keepAwake(true);const el=document.getElementById("breath");el.innerHTML='<div class="q-top"><span style="flex:1"></span><button onclick="L.breathStop()" aria-label="Close">×</button></div><div class="b-wrap"><div class="b-circle" id="bC"><span id="bP">Ready</span></div><div class="b-left" id="bL">'+fmtTime(secs)+'</div></div>';el.classList.add("open");
 B={k:k,total:secs,left:secs,i:-1,phLeft:0,start:Date.now(),int:null};setTimeout(()=>{if(!B)return;bPhase();B.int=setInterval(bTick,1000)},800)}
function bPhase(){const ph=BREATHS[B.k].ph;B.i=(B.i+1)%ph.length;const p=ph[B.i];B.phLeft=p[1];const c=document.getElementById("bC"),t=document.getElementById("bP");if(!c)return;c.style.transitionDuration=p[1]+"s";c.style.transform=p[0]==="In"?"scale(1)":p[0]==="Out"?"scale(.55)":c.style.transform;t.textContent=p[0];if(settings.voice)say(p[0]==="In"?"In":p[0]==="Out"?"Out":"Hold");else beep(p[0]==="In"?660:520,.06)}
function bTick(){if(!B)return;B.left--;B.phLeft--;const l=document.getElementById("bL");if(l)l.textContent=fmtTime(B.left);if(B.left<=0){const done=B.total;breathStop(true);D().b=(D().b||0)+done;saveDaily();beep(1046,.3);toast("Nicely done 🌬️");renderLifeToday();return}if(B.phLeft<=0)bPhase()}
function breathStop(fin){if(!B)return;clearInterval(B.int);const used=B.total-B.left;if(!fin&&used>=30){D().b=(D().b||0)+used;saveDaily()}B=null;keepAwake(false);try{speechSynthesis.cancel()}catch(e){}document.getElementById("breath").classList.remove("open");renderLifeToday()}

/* ---------- tips ---------- */
const TIPS=["Drink a glass of water as soon as you get up.","Have some protein with every meal. It keeps you fuller for longer and helps your muscles recover.","Seven to nine hours of sleep does more for your body than any supplement.","If your last set felt easy, go up a little in weight next time.","A ten minute walk after your biggest meal helps your body handle it.","Slow down the lowering part of each rep. It's where a lot of the work happens.","Lay your kit out the night before. It makes starting much easier.","Breathe out as you push or lift, and in as you lower.","Fill half your plate with vegetables or salad.","Missed a day? Just do the next one. One gap is nothing, two in a row is where habits slip.","Stand up and move for a couple of minutes every hour you sit.","Keep a water bottle where you can see it.","Brace your stomach before every rep, as if someone is about to poke you.","Progress photos and a tape measure tell you more than the scales.","Weigh yourself at the same time of day, ideally first thing in the morning.","Cut back on sugary drinks before you cut back on food.","Shoulders down and back, chin tucked. Good posture starts with that.","Soreness a day or two after a new workout is normal. Sharp pain is not, so stop.","A short workout is always better than no workout.","Eat slowly. It takes about twenty minutes for your stomach to tell your brain it's full.","Take the stairs whenever you can. It all adds up.","Plan your workouts like appointments and put them in your calendar.","Stretch your hips and chest if you sit a lot.","Good form first, then heavier weights.","Keep healthy snacks ready so you're not grabbing biscuits.","Track the wins that aren't on the scales: sleep, energy, how your clothes fit.","Warm up for a few minutes. Your joints will thank you.","Swap one takeaway a week for a home cooked version.","Rest days are part of the plan, not a break from it.","Small changes kept up for months beat big changes kept up for a week."];
let tipOff=0;
function tip(){const n=Math.floor(Date.now()/864e5)+tipOff;return TIPS[((n%TIPS.length)+TIPS.length)%TIPS.length]}

/* ---------- Today ---------- */
function renderLifeToday(){const el=document.getElementById("lifeToday");if(!el)return;const p=prof(),m=mods(),t=targets(),d=D();let h="";
 if(!p&&settings.setupDone)h+='<div class="card" style="cursor:pointer;border-color:var(--lime)" onclick="L.openQuiz()"><div class="row"><div><h3>Personalise your plan</h3><p class="tiny" style="margin:0">One minute of quick taps. Goal, body and daily targets.</p></div><span style="font-size:28px">✨</span></div></div>';
 if(chal.cur){const c=chById(chal.cur.id),days=chDays(c),nx=chNext(),dn=Object.keys(chal.cur.done).length,w=days[nx];h+='<div class="card" style="cursor:pointer" onclick="L.openCh(\''+c.id+'\')"><div class="row"><div style="min-width:0"><span class="eyebrow">CHALLENGE · DAY '+(nx+1)+' OF '+days.length+'</span><h3 style="margin:4px 0 0">'+esc(c.name)+'</h3><p class="tiny" style="margin:2px 0 0">'+(w===REST?"Rest day today":"Today: "+esc(W[w].name))+'</p></div><button class="btn small" style="background:var(--grad);color:#fff;flex:none" onclick="event.stopPropagation();'+(w===REST?"L.chRest("+nx+")":"L.chGo("+nx+")")+'">'+(w===REST?"✓ Rest":"GO")+'</button></div><div class="hbar"><i style="width:'+(dn/days.length*100)+'%"></i></div></div>'}
 const rows=[];
 if(m.water){const g=Math.round(t.water/250),cur=Math.round((d.w||0)/250);rows.push('<div class="habit"><span class="ic">💧</span><div class="tx"><b>Water</b><small>'+litres(d.w||0)+' of '+litres(t.water)+' litres</small><div class="glasses">'+Array.from({length:g},(_,i)=>'<button class="'+(i<cur?"on":"")+'" onclick="L.water('+i+')" aria-label="Glass '+(i+1)+'"></button>').join("")+'</div></div><span class="tick'+(cur>=g?" on":"")+'">'+(cur>=g?"✓":"")+'</span></div>')}
 if(m.steps){const s=d.s||0;rows.push('<div class="habit" style="cursor:pointer" onclick="L.openSteps()"><span class="ic">👟</span><div class="tx"><b>Steps</b><small>'+s.toLocaleString("en-GB")+' of '+t.steps.toLocaleString("en-GB")+' · tap to add</small><div class="hbar"><i style="width:'+Math.min(100,s/t.steps*100)+'%"></i></div></div><span class="tick'+(s>=t.steps?" on":"")+'">'+(s>=t.steps?"✓":"")+'</span></div>')}
 if(m.meals){const r=todaysMeal(),n=(d.m||[]).length;rows.push('<div class="habit" style="cursor:pointer" onclick="L.recipe(\''+r.id+'\')"><span class="ic">'+r.em+'</span><div class="tx"><b>'+esc(r.n)+'</b><small>'+MEALS[r.m]+' idea · '+r.kcal+' kcal · '+r.min+' min</small></div><button class="linkbtn" onclick="event.stopPropagation();L.openMeals(\''+r.m+'\')">'+(n?n+" had":"More")+'</button></div>')}
 if(m.mind){const b=d.b||0;rows.push('<div class="habit" style="cursor:pointer" onclick="L.openBreath()"><span class="ic">🌬️</span><div class="tx"><b>Breathe</b><small>'+(b?Math.round(b/60)+" min today":"1 minute to reset")+'</small></div><span class="tick'+(b>=60?" on":"")+'">'+(b>=60?"✓":"")+'</span></div>');
  rows.push('<div class="habit"><span class="ic">🙂</span><div class="tx"><b>How are you feeling?</b><div class="moods">'+["😫","😕","😐","🙂","😄"].map((e,i)=>'<button class="'+(d.mood===i+1?"on":"")+'" onclick="L.mood('+(i+1)+')">'+e+'</button>').join("")+'</div></div></div>')}
 if(m.tips)rows.push('<div class="habit" style="cursor:pointer" onclick="L.nextTip()"><span class="ic">💡</span><div class="tx"><b>Tip of the day</b><small style="color:var(--ink2);font-size:13px;line-height:1.4">'+esc(tip())+'</small></div><span style="color:var(--muted)">›</span></div>');
 if(rows.length)h+='<div class="section-head"><h2>Your day</h2></div><div class="card" style="padding:4px 16px">'+rows.join("")+'</div>';
 el.innerHTML=h}

/* ---------- Workouts page: challenges ---------- */
function renderLifeTrain(){const el=document.getElementById("lifeChallenges");if(!el)return;el.innerHTML='<div class="section-head" style="margin-top:6px"><h2>Challenges</h2></div><div class="hscroll" style="display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:6px;margin-bottom:8px">'+CH.slice().sort((a,b)=>(chal.cur&&b.id===chal.cur.id)-(chal.cur&&a.id===chal.cur.id)).map(chCard).join("")+'</div>'}

/* ---------- Progress page: body, habits, badges ---------- */
function renderLifeProgress(){const el=document.getElementById("lifeBody");if(!el)return;const s=bodyStats(),p=prof(),b=bmi(),t=targets(),m=mods();
 let h='<div class="card"><div class="row"><h3>Body</h3><button class="btn small" style="background:var(--grad);color:#fff" onclick="L.logWeight()">+ Weight</button></div>';
 h+=s?'<div class="facts3"><div><b>'+wtTxt(s.last)+'</b><small>NOW</small></div><div><b>'+(body.w.length>1?diffTxt(s.change):"·")+'</b><small>SINCE START</small></div><div><b>'+(p&&p.gw&&Math.abs(s.left)>=0.1?diffTxt(-s.left).replace(/^[+−]/,""):p&&p.gw?"✓":"·")+'</b><small>'+(p&&p.gw?"TO GOAL":"NO GOAL SET")+'</small></div></div>':'<p class="tiny">Log your weight to start your chart.</p>';
 h+=weightChart();if(b)h+='<p class="tiny" style="margin:8px 0 0">BMI '+b.toFixed(1)+', '+bmiBand(b)+'. BMI is a rough guide and doesn\'t know about muscle.</p>';
 h+='<div class="row" style="gap:8px;margin-top:12px"><button class="btn soft" style="flex:1" onclick="L.openMeas()">📏 Measurements</button><button class="btn soft" style="flex:1" onclick="L.openPhotos()">📷 Photos</button></div></div>';
 if(m.water||m.steps){const days=[];for(let i=6;i>=0;i--){const dt=new Date();dt.setDate(dt.getDate()-i);days.push({l:DAYS[dow(dt)].slice(0,1),d:daily[dayKey(dt)]||{}})}
  const bar=(v,g)=>'<span style="display:block;height:'+Math.max(4,Math.min(1,v/g)*60)+'px;border-radius:6px;background:'+(v>=g?"var(--grad)":"#2a2a31")+'"></span>';
  h+='<div class="card"><h3>Last 7 days</h3>'+(m.water?'<div class="tiny" style="margin:10px 0 4px">💧 Water</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:6px;align-items:end;height:64px">'+days.map(x=>bar(x.d.w||0,t.water)).join("")+'</div>':'')+(m.steps?'<div class="tiny" style="margin:12px 0 4px">👟 Steps</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:6px;align-items:end;height:64px">'+days.map(x=>bar(x.d.s||0,t.steps)).join("")+'</div>':'')+'<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:6px;text-align:center;margin-top:4px">'+days.map(x=>'<small class="tiny">'+x.l+'</small>').join("")+'</div></div>'}
 el.innerHTML=h;
 const bl=badgeList(),on=bl.filter(x=>x[3]).length;document.getElementById("lifeBadges").innerHTML='<div class="section-head"><h2>Badges</h2><span class="tiny">'+on+' of '+bl.length+'</span></div><div class="card"><div class="badges">'+bl.map(x=>'<div class="badge'+(x[3]?" on":"")+'"><div class="bx">'+x[1]+'</div><small>'+x[2]+'</small></div>').join("")+'</div></div>'}

/* ---------- Settings ---------- */
function renderLifeSettings(){const el=document.getElementById("lifeSettings");if(!el)return;const p=prof(),m=mods(),g=p&&GOALS.find(x=>x[0]===p.goal);
 const tog=(k,lbl)=>'<label>'+lbl+'</label><div class="seg"><button class="'+(m[k]?"active":"")+'" onclick="L.mod(\''+k+'\',true)">On</button><button class="'+(!m[k]?"active":"")+'" onclick="L.mod(\''+k+'\',false)">Off</button></div>';
 el.innerHTML='<div class="card"><h3>About you</h3><p class="tiny">'+(p?esc(g[2])+" · "+(p.age)+" years · "+htTxt(p.h)+" · goal "+wtTxt(p.gw):"Not set up yet")+'</p><button class="btn soft full" onclick="L.openQuiz()">'+(p?"Retake the quiz":"Personalise my plan")+'</button>'+
 '<label>Body weight in</label><div class="seg"><button class="'+(settings.bodyUnit!=="st"?"active":"")+'" onclick="L.su(\'bodyUnit\',\'kg\')">kg</button><button class="'+(settings.bodyUnit==="st"?"active":"")+'" onclick="L.su(\'bodyUnit\',\'st\')">st and lb</button></div><label>Height in</label><div class="seg"><button class="'+(settings.hUnit!=="ft"?"active":"")+'" onclick="L.su(\'hUnit\',\'cm\')">cm</button><button class="'+(settings.hUnit==="ft"?"active":"")+'" onclick="L.su(\'hUnit\',\'ft\')">ft and in</button></div></div>'+
 '<div class="card"><h3>On your Today screen</h3>'+tog("water","💧 Water")+tog("steps","👟 Steps")+tog("meals","🥗 Meal ideas")+tog("mind","🌬️ Breathing and mood")+tog("tips","💡 Daily tip")+'</div>'}
function setMod(k,v){if(!settings.profile)settings.profile={mods:mods()};settings.profile.mods=Object.assign(mods(),{[k]:v});saveSet();renderLifeSettings();renderLifeToday()}
function su(k,v){settings[k]=v;saveSet();renderLifeSettings();afterLife()}

/* ---------- wiring ---------- */
function afterLife(){renderLifeToday();if(document.getElementById("progress").classList.contains("active"))renderLifeProgress();if(document.getElementById("train").classList.contains("active"))renderLifeTrain()}
const _rh=renderHome;window.renderHome=renderHome=function(){_rh();renderLifeToday()};
const _rt=renderTrain;window.renderTrain=renderTrain=function(){_rt();renderLifeTrain()};
const _rp=renderProgress;window.renderProgress=renderProgress=function(){_rp();renderLifeProgress()};
